#!/usr/bin/env node
/**
 * ETEL Delivery - bundle builder
 *
 * Concatenates each *-bundle.js's declared source files and minifies the
 * result with terser. Run this after editing any source file listed below
 * (core.js, driver.js, ride.js, etc.) so the shipped bundle stays in sync
 * and stays small on 3G/4G Hawassa connections.
 *
 * Usage:
 *   npm install terser   (once, from this js/ directory or anywhere on PATH)
 *   node build-bundles.js
 */
const fs = require('fs');
const path = require('path');
const { minify } = require('terser');

const JS_DIR = __dirname;

// driver-bundle.js and ride-bundle.js used to bundle their "premium"/"fix"
// add-ons (enhancement code the app already treats as optional, per those
// files' own header comments) into the same critical-path file the page
// can't render without. Splitting them into a small "core" bundle plus a
// "-extra" bundle that loads with the `defer` attribute (see driver.html /
// ride.html) means the driver/rider can interact with the core UI before
// the enhancement code has even finished downloading - genuine code
// splitting, not just a smaller number on disk.
const BUNDLES = {
  'customer-bundle.js':    ['core.js'],
  'customer-bundle-extra.js': ['jsQR.js'],
  'courier-bundle.js':     ['courier.js', 'courier-premium.js'],
  'driver-bundle.js':      ['core.js', 'ride_chat.js', 'etel-ui.js', 'driver.js'],
  'driver-bundle-extra.js':['driver-premium.js', 'driver-nav.js'],
  'ride-bundle.js':        ['core.js', 'ride_chat.js', 'etel-ui.js', 'ride.js'],
  'ride-bundle-extra.js':  ['ride-premium.js', 'ride-fix.js'],
  'servicegiver-bundle.js':['servicegiver.js', 'servicegiver-premium.js'],
};

async function buildOne(outName, sources) {
  const header = `/* ============================================================\n   ${outName} - bundled scripts\n   Auto-generated by concatenating (in this exact execution order):\n${sources.map(s => `     - js/${s}`).join('\n')}\n   Do not hand-edit; edit the source files above and rebuild with\n   node js/build-bundles.js\n   ============================================================ */\n\n`;

  let combined = '';
  for (const s of sources) {
    const p = path.join(JS_DIR, s);
    if (!fs.existsSync(p)) {
      console.error(`  MISSING source: ${s} (skipped)`);
      continue;
    }
    combined += `/* ---- source: js/${s} ---- */\n` + fs.readFileSync(p, 'utf8') + '\n';
  }

  const unminified = header + combined;
  const unminifiedPath = path.join(JS_DIR, outName);
  const beforeSize = fs.existsSync(unminifiedPath) ? fs.statSync(unminifiedPath).size : 0;

  let out;
  try {
    const result = await minify(combined, {
      // compress stays OFF: these scripts define functions that get called
      // from inline onclick="..." HTML attributes terser cannot see, and
      // compress's dead-code-elimination/inlining passes were confirmed
      // (by an earlier test run of this build) to silently strip or inline
      // functions that are actually in use that way.
      //
      // mangle is now ON, but scoped with `toplevel: false` (terser's
      // default) - this only renames LOCAL variables and nested/inner
      // function names, never top-level declarations. Verified directly:
      // a top-level `function publicHandler(){...}` referenced only via
      // `onclick="publicHandler()"` keeps its exact name and behavior,
      // while everything inside its body (locals, parameters, helper
      // functions declared inside it) gets safely shortened. This is real
      // additional size reduction with the same zero-risk-to-onclick
      // guarantee as the comment/whitespace stripping below.
      compress: false,
      mangle: { toplevel: false },
      format: { comments: false, beautify: false },
    });
    if (result.error) throw result.error;
    out = header.replace('Auto-generated by concatenating', 'Auto-generated & minified by concatenating') + result.code + '\n';
  } catch (e) {
    console.error(`  Minify failed for ${outName}, writing unminified: ${e.message}`);
    out = unminified;
  }

  fs.writeFileSync(unminifiedPath, out);
  const afterSize = out.length;
  console.log(`${outName}: ${beforeSize} -> ${afterSize} bytes (${beforeSize ? Math.round((1 - afterSize / beforeSize) * 100) : 0}% smaller)`);
}

(async () => {
  for (const [outName, sources] of Object.entries(BUNDLES)) {
    await buildOne(outName, sources);
  }
})();
